// Generated by llm-config setup. Edit the source template, then reinstall.
const patterns = __RESOURCE_PATTERNS__;

// OpenCode accepts both action strings and pattern maps.
const rules = (value) => typeof value === "string" ? { "*": value } : (value ?? {});

export default async () => ({
  config(config) {
    const permission = rules(config.permission);
    for (const tool of ["external_directory", "read"]) {
      const existing = rules(permission[tool]);
      // Put grants last: OpenCode uses the last matching pattern. Delete first
      // so reinstalling/reapplying cannot leave a grant before a broad rule.
      const merged = { ...existing };
      for (const pattern of patterns) delete merged[pattern];
      for (const pattern of patterns) merged[pattern] = "allow";
      permission[tool] = merged;
    }
    config.permission = permission;
  },
});
